//! The generated types against the C compiler: tests/data/c-layout.txt is what host/gen/drm/tests/probe.c prints
//! when built with GCC against the CachyOS headers (sizeof, _Alignof, offsetof, constant values); the table in
//! tests/data/layout_table.rs is the same facts from the Rust types. Both are regenerated by drm-gen.

use core::mem::{align_of, offset_of, size_of};
use std::collections::BTreeMap;

use ::drm::ioc;
use ::drm::uapi::*;

include!("data/layout_table.rs");

const C: &str = include_str!("data/c-layout.txt");

fn c_facts(kind: &str) -> BTreeMap<String, Vec<i128>> {
    let mut m = BTreeMap::new();
    for l in C.lines().filter(|l| l.starts_with(kind)) {
        let t: Vec<&str> = l.split_whitespace().collect();
        let nums = t.iter().skip_while(|s| s.parse::<i128>().is_err()).map(|s| s.parse().unwrap()).collect();
        let key = t[1..t.len() - t.iter().filter(|s| s.parse::<i128>().is_ok()).count()].join(" ");
        assert!(m.insert(key.clone(), nums).is_none(), "{kind} {key} twice in c-layout.txt");
    }
    m
}

#[test]
fn sizes_and_alignments_match_gcc() {
    let c = c_facts("type ");
    for (name, size, align) in TYPES {
        assert_eq!(c.get(*name), Some(&vec![*size as i128, *align as i128]), "type {name}: Rust size {size} align {align}");
    }
    assert_eq!(c.len(), TYPES.len());
}

#[test]
fn field_offsets_match_gcc() {
    let c = c_facts("field ");
    for (ty, f, off) in FIELDS {
        assert_eq!(c.get(&format!("{ty} {f}")), Some(&vec![*off as i128]), "{ty}.{f}: Rust offset {off}");
    }
    assert_eq!(c.len(), FIELDS.len());
}

#[test]
fn constants_and_ioctl_numbers_match_gcc() {
    let c = c_facts("const ");
    for (name, v) in CONSTS {
        assert_eq!(c.get(*name), Some(&vec![*v as i128]), "{name}: Rust {v:#x}");
    }
    assert_eq!(c.len(), CONSTS.len());
}

#[test]
fn ioctl_size_field_is_the_rust_argument_size() {
    for (name, cmd, size) in IOCTLS {
        assert_eq!(ioc::size(*cmd) as usize, *size, "{name}");
        assert_ne!(ioc::dir(*cmd), ioc::IOC_NONE, "{name}");
    }
}

#[test]
fn every_ioctl_is_in_a_table() {
    let all = [DRM_IOCTLS, AMDGPU_IOCTLS, SYNC_FILE_IOCTLS, DMA_BUF_IOCTLS].concat();
    assert_eq!(all.len(), 138);
    assert!(IOCTLS.iter().all(|(n, c, _)| all.contains(&(*n, *c))));
}

/// Hostile sizes and the padding rule on every generated type, since DR-2 feeds `Wire` with caller-sized buffers.
fn wire_contract<T: ::drm::Wire + PartialEq + core::fmt::Debug>(name: &str) {
    let n = T::SIZE;
    assert_eq!(n, size_of::<T>(), "{name}");
    // Distinct non-zero bytes, so a field read or written at the wrong offset shows up as a changed byte.
    let pat: std::vec::Vec<u8> = (0..n + 8).map(|i| (i % 251 + 1) as u8).collect();
    if n > 0 {
        assert_eq!(T::decode(&pat[..n - 1]), None, "{name}: short decode");
        assert_eq!(T::ZERO.encode(&mut std::vec![0u8; n - 1]), None, "{name}: short encode");
    }
    let v = T::decode(&pat).unwrap_or_else(|| panic!("{name}: decode of size+8 bytes"));
    let mut out = std::vec![0xaau8; n + 8];
    v.encode(&mut out).unwrap_or_else(|| panic!("{name}: encode"));
    assert!(out[n..].iter().all(|&b| b == 0xaa), "{name}: wrote past sizeof");
    // Every byte is either the caller's data, back at its offset, or padding written as zero.
    for i in 0..n {
        assert!(out[i] == pat[i] || out[i] == 0, "{name}: byte {i} is {:#x}, neither data {:#x} nor zero", out[i], pat[i]);
    }
    assert_eq!(T::decode(&out), Some(v), "{name}: round trip");
    let mut z = std::vec![0xaau8; n];
    T::ZERO.encode(&mut z).unwrap();
    assert!(z.iter().all(|&b| b == 0), "{name}: ZERO is not all zero bytes");
}

#[test]
fn wire_contract_holds_for_every_type() {
    let mut seen = std::collections::BTreeSet::new();
    macro_rules! check {
        ($t:ident) => {{
            wire_contract::<$t>(stringify!($t));
            assert!(seen.insert(stringify!($t)));
        }};
    }
    for_each_type!(check);
    let known: std::collections::BTreeSet<&str> = TYPES.iter().map(|t| t.0).chain(FIELDS.iter().map(|f| f.0)).collect();
    assert_eq!(seen, known, "for_each_type and the layout tables name different types");
}
